name: Setup
description: Set up runtimes and repository tools

# pretty-yaml-ignore
inputs:
  install-runner:    { description: Install runner-run,          required: false, default: "true"   }
  install-deno:      { description: Install Deno,                required: false, default: "false"  }
  deno-version:      { description: Deno version to install,     required: false, default: "2.x"    }
  install-bun:       { description: Install Bun,                 required: false, default: "true"   }
  bun-version:       { description: Bun version to install,      required: false, default: "latest" }
  install-node:      { description: Install Node.js,             required: false, default: "true"   }
  node-version:      { description: Node version to install,     required: false, default: "file"   }
  node-registry-url: { description: "npm registry URL for Node", required: false, default: ""       }
  update-npm:        { description: "Update npm to 11",          required: false, default: "true"   }

# pretty-yaml-ignore
outputs:
  runner-version: { description: The installed runner version,  value: "${{ steps.setup-runner.outputs.version    }}" }
  deno-version:   { description: The installed Deno version,    value: "${{ steps.setup-deno.outputs.deno-version }}" }
  bun-version:    { description: The installed Bun version,     value: "${{ steps.setup-bun.outputs.bun-version   }}" }
  bun-path:       { description: The installed Bun path,        value: "${{ steps.setup-bun.outputs.bun-path      }}" }
  node-version:   { description: The installed Node.js version, value: "${{ steps.setup-node.outputs.node-version }}" }
  npm-version:    { description: The installed npm version,     value: "${{ steps.update-npm.outputs.npm-version  }}" }

runs:
  using: composite
  steps:
    - name: Setup runner-run
      id: setup-runner
      if: ${{ inputs.install-runner == 'true' }}
      uses: kjanat/runner@b32ea932a1813ae0be44e755c16df9f9f5ca86a4 # v0.28.0

    - name: Setup tombi
      uses: kjanat/setup-tombi@94a6834e289046705b32e6b8dc977c8b939e8b35 # v1

    - name: Setup dprint
      uses: kjanat/dprint-check@29c42153a7346f4d7315883ff7722cfe22cd510c # v3.1.0
      with: { install-only: true }

    - name: Setup Deno
      id: setup-deno
      if: ${{ inputs.install-deno == 'true' }}
      uses: denoland/setup-deno@22d081ff2d3a40755e97629de92e3bcbfa7cf2ed # v2.0.5
      with: { deno-version: "${{ inputs.deno-version }}" }

    - name: Setup Node
      id: setup-node
      if: ${{ inputs.install-node == 'true' }}
      uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
      with:
        node-version: ${{ case(inputs.node-version != 'file', inputs.node-version, '') }}
        node-version-file: ${{ case(inputs.node-version == 'file','.node-version', '') }}
        package-manager-cache: false
        registry-url: ${{ inputs.node-registry-url }}

    - name: Setup Bun
      id: setup-bun
      if: ${{ inputs.install-bun == 'true' }}
      uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2.2.0
      with: { bun-version: "${{ inputs.bun-version }}" }

    - name: Update npm
      id: update-npm
      if: ${{ inputs.install-node == 'true' && inputs.update-npm == 'true' }}
      shell: "bash -euo pipefail {0}"
      run: |
        npm install -g npm@11
        npm_version=$(npm --version)
        echo "npm-version=${npm_version}" >> "${GITHUB_OUTPUT}"

