name: Claude Code
on:
  issue_comment: { types: [created] }
  pull_request_review_comment: { types: [created] }
  issues: { types: [opened, assigned] }
  pull_request_review: { types: [submitted] }
permissions: { contents: read }
defaults: { run: { shell: "bash -euo pipefail {0}" } }

jobs:
  claude:
    if: |
      github.repository == 'kjanat/micro509' &&
      (github.event.comment.user.login || github.event.review.user.login || github.event.issue.user.login) == 'kjanat' && (
        (github.event_name == 'issue_comment' && contains(github.event.comment.body, '@claude')) ||
        (github.event_name == 'pull_request_review_comment' && contains(github.event.comment.body, '@claude')) ||
        (github.event_name == 'pull_request_review' && contains(github.event.review.body, '@claude')) ||
        (github.event_name == 'issues' && (contains(github.event.issue.body, '@claude') || contains(github.event.issue.title, '@claude')))
      )
    runs-on: ubuntu-latest
    timeout-minutes: 60
    permissions: { contents: write, pull-requests: write, issues: write, id-token: write, actions: read }
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with:
          fetch-depth: 0
          persist-credentials: false
          ref: ${{ github.event.repository.default_branch }}
      - { uses: $/.github/actions/setup, id: setup, with: { install-bun: "true", install-node: "true" } }
      - name: Install dependencies and build
        run: runner install -f build

      - name: Run Claude Code
        id: claude
        uses: anthropics/claude-code-action@93f0fe1f6f57c1c6047dddacd7d728ecec7f28a7 # v1
        with:
          claude_code_oauth_token: ${{ secrets.CLAUDE_CODE_OAUTH_TOKEN }}
          path_to_bun_executable: ${{ steps.setup.outputs.bun-path }}
          settings: ${{ vars.CLAUDE_SETTINGS }}
          additional_permissions: "actions: read"

