name: OpenSSL
run-name: ${{ inputs.version && format('OpenSSL + {0}', inputs.version) || 'OpenSSL' }}
on:
  schedule: [cron: "23 5 * * *"]
  workflow_dispatch:
    inputs:
      version:
        description: "Also publish this/these OpenSSL releases, comma-separated, e.g. 3.5.5,3.4.2"
        type: string
        default: ""
        required: false
      force:
        description: Rebuild versions that are already published
        type: boolean
        default: false
        required: false

permissions: { contents: read }

# pretty-yaml-ignore
env:
  FORCE:    ${{ inputs.force || false }}
  IMAGE:    'ghcr.io/${{ github.repository_owner }}/openssl'
  PREBUILT: 'ghcr.io/${{ github.repository_owner }}/openssl-prebuilt'
  USAGE:    '${{ github.server_url }}/${{ github.repository }}/tree/${{ github.event.repository.default_branch }}/.github/openssl#readme'
  BUILD:    run${{ github.run_id }}.${{ github.run_attempt }}

defaults: { run: { shell: "bash -euo pipefail {0}" } }

jobs:
  resolve:
    name: Resolve versions
    if: github.repository == 'kjanat/micro509'
    runs-on: &Ubuntu ubuntu-26.04
    timeout-minutes: 5
    permissions: { contents: read, packages: read }
    # pretty-yaml-ignore
    outputs:
      releases:   ${{ steps.resolve.outputs.releases }}
      publishes:  ${{ steps.resolve.outputs.publishes }}
      latest:     ${{ steps.resolve.outputs.latest }}
      alpha:      ${{ steps.resolve.outputs.alpha }}
      beta:       ${{ steps.resolve.outputs.beta }}
      date:       ${{ steps.resolve.outputs.date }}
    steps:
      - id: resolve
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env: { VERSION: "${{ inputs.version }}" }
        with:
          retries: 3
          result-encoding: "json"
          script: |
            const openssl = { owner: 'openssl', repo: 'openssl' };
            const pattern = /^\d+\.\d+\.\d+(-(alpha|beta)\d+)?$/;
            const strip   = (tag) => tag?.replace(/^openssl-/, '') ?? '';
            const { IMAGE, PREBUILT, FORCE, VERSION } = process.env;

            async function tags(image) {
              const [, username, package_name] = image.split('/');
              try {
                const versions = await github.paginate(github.rest.packages.getAllPackageVersionsForPackageOwnedByUser, {
                  package_type: 'container', package_name, username, per_page: 100,
                });
                return new Set(versions.flatMap((version) => version.metadata.container.tags));
              } catch (error) {
                if (error.status === 404) return new Set();
                throw error;
              }
            }

            const { data: latestRelease } = await github.rest.repos.getLatestRelease(openssl);
            const { data: releases }      = await github.rest.repos.listReleases({ ...openssl, per_page: 100 });
            const latest     = strip(latestRelease.tag_name);
            const newest     = (kind) => strip(releases.find((release) => release.prerelease && !release.draft && release.tag_name.includes(`-${kind}`))?.tag_name);
            const alpha      = newest('alpha');
            const beta       = newest('beta');
            const requested  = VERSION.split(/[\s,]+/);
            const versions   = [...new Set([latest, alpha, beta, ...requested].filter(Boolean))];

            const imageTags    = await tags(IMAGE);
            const prebuiltTags = await tags(PREBUILT);
            const entries      = [];
            for (const version of versions) {
              if (!pattern.test(version)) throw new Error(`${version} is not an OpenSSL release such as 3.5.5 or 4.1.0-beta1.`);
              if (FORCE !== 'true' && imageTags.has(version) && prebuiltTags.has(version)) {
                core.notice(`${IMAGE}:${version} and ${PREBUILT}:${version} are already published`);
                continue;
              }
              const { data: release } = await github.rest.repos.getReleaseByTag({ ...openssl, tag: `openssl-${version}` });
              const asset  = release.assets.find(({ name }) => name === `openssl-${version}.tar.gz`);
              const file   = release.assets.find(({ name }) => name === `openssl-${version}.tar.gz.sha256`);
              const listed = asset?.digest ?? (file && `sha256:${await (await fetch(file.browser_download_url)).text()}`);
              const sha256 = listed?.match(/^sha256:([0-9a-f]{64})\b/)?.[1];
              if (!sha256) throw new Error(`openssl-${version}.tar.gz has no SHA-256 digest on its release.`);
              entries.push({ version, sha256 });
            }

            core.setOutput('latest', latest);
            core.setOutput('alpha', alpha);
            core.setOutput('beta', beta);
            core.setOutput('date', new Date().toISOString().slice(0, 10).replaceAll('-', ''));
            core.setOutput('releases', JSON.stringify(entries));
            core.setOutput('publishes', JSON.stringify(['none', ...entries]));

  image:
    name: Image ${{ matrix.release.version }}
    needs: resolve
    if: &ReleasesNonEmpty needs.resolve.outputs.releases != '[]'
    runs-on: *Ubuntu
    timeout-minutes: 30
    permissions: &WritePkgAttestIdToken { contents: read, packages: write, id-token: write, attestations: write }
    strategy: { fail-fast: true, matrix: { release: "${{ fromJSON(needs.resolve.outputs.releases) }}" } }
    steps:
      - &SafeCheckout { uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1, with: { persist-credentials: false } }
      - parallel:
          - uses: docker/setup-buildx-action@f87e5991a6d7451dcb8d9637bfbc97413f497069 # v4.4.1
          - { uses: &Oras oras-project/setup-oras@005458ad77f1c8facd38a094e4af2e69e5607ff4 } # v2.0.2
          - uses: docker/login-action@81c6f93d4bc991e510b342a00b419b3bb4efc5c6 # v4.7.0
            with: { registry: ghcr.io, username: "${{ github.actor }}", password: &GHToken "${{ github.token }}" }
      - id: meta
        uses: docker/metadata-action@dc802804100637a589fabce1cb79ff13a1411302 # v6.2.0
        with:
          images: &Image ${{ env.IMAGE }}
          flavor: latest=false
          tags: type=raw,value=${{ matrix.release.version }}-${{ env.BUILD }}
          labels: &DockerMeta |
            org.opencontainers.image.title=openssl
            org.opencontainers.image.description=OpenSSL ${{ matrix.release.version }}, statically linked, built from the upstream release tarball. Usage: ${{ env.USAGE }}
            org.opencontainers.image.version=${{ matrix.release.version }}
            dev.kjanat.openssl.upstream.tag=openssl-${{ matrix.release.version }}
            org.opencontainers.image.licenses=Apache-2.0
          annotations: *DockerMeta
      - name: Build and export SBOMs
        uses: &DockerBP docker/build-push-action@c3c9e263c25d99ce0380d002d59b67737d91b0dc # v7.4.0
        with:
          context: &DockerCtx .github/openssl
          build-args: &BuildArgs |
            VERSION=${{ matrix.release.version }}
            SHA256=${{ matrix.release.sha256 }}
          provenance: false
          sbom: true
          outputs: type=local,dest=${{ runner.temp }}/export
      - name: Push
        id: push
        if: &IsMaster github.ref == 'refs/heads/master'
        uses: *DockerBP
        with:
          context: *DockerCtx
          build-args: *BuildArgs
          provenance: false
          sbom: false
          push: true
          tags: ${{ steps.meta.outputs.tags }}
          labels: ${{ steps.meta.outputs.labels }}
          annotations: ${{ steps.meta.outputs.annotations }}
      - name: Tag date and version
        if: *IsMaster
        env:
          v: &MatrixRelease ${{ matrix.release.version }}
          i: ${{ format('{0}@{1}', env.IMAGE, steps.push.outputs.digest) }}
          date: ${{ needs.resolve.outputs.date }}
        run: for t in "${v}-${date}" "${v}"; do oras tag "${i}" "${t}"; done
      - name: Unwrap SPDX documents and pack the linux-x64 tarball
        working-directory: ${{ runner.temp }}
        env:
          v: *MatrixRelease
          spdx_image: ${{ runner.temp }}/image.spdx.json
          spdx_build: ${{ runner.temp }}/build.spdx.json
        run: |
          printf 'spdx_image=%s\nspdx_build=%s\n' "${spdx_image}" "${spdx_build}" >> "${GITHUB_ENV}"
          jq '.predicate' "export/sbom.spdx.json"       > "${spdx_image}"
          jq '.predicate' "export/sbom-build.spdx.json" > "${spdx_build}"
          tar -C export/usr/local -czf "openssl-${v}-linux-x64.tar.gz" .
      - uses: &Attest actions/attest@1e69f48acb82d1966a394da916b4c1698aa569d6 # v4.2.2
        if: *IsMaster
        with:
          subject-name: *Image
          subject-digest: &Digest ${{ steps.push.outputs.digest }}
          create-storage-record: false
      - uses: *Attest
        if: *IsMaster
        with:
          subject-name: *Image
          subject-digest: *Digest
          sbom-path: ${{ env.spdx_image }}
          create-storage-record: false
      - uses: *Attest
        if: *IsMaster
        with:
          subject-name: *Image
          subject-digest: *Digest
          sbom-path: ${{ env.spdx_build }}
          create-storage-record: false
      - uses: &Upload actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
        with:
          name: openssl-${{ matrix.release.version }}-linux-x64
          path: ${{ runner.temp }}/openssl-${{ matrix.release.version }}-linux-x64.tar.gz
          if-no-files-found: error
          retention-days: 1

  tarball:
    name: ${{ matrix.release.version }} ${{ matrix.platform }}
    needs: resolve
    if: *ReleasesNonEmpty
    runs-on: ${{ matrix.runner }}
    timeout-minutes: 45
    permissions: { contents: read }
    strategy:
      fail-fast: true
      matrix:
        release: ${{ fromJSON(needs.resolve.outputs.releases) }}
        platform: [linux-arm64, darwin-x64, darwin-arm64, windows-x64, windows-arm64]
        # pretty-yaml-ignore
        include: [
          { platform: darwin-arm64,  runner: macos-15         },
          { platform: darwin-x64,    runner: macos-15-intel   },
          { platform: linux-arm64,   runner: ubuntu-26.04-arm },
          { platform: windows-arm64, runner: windows-11-vs2026-arm, msvc-arch: arm64, configure-targets: [VC-WIN64-CLANGASM-ARM, VC-WIN64-ARM], tool: clang-cl },
          { platform: windows-x64,   runner: windows-2025-vs2026,   msvc-arch: x64,   configure-targets: [VC-WIN64A],                           tool: nasm     },
          ]
    env:
      VERSION: *MatrixRelease
      SHA256: ${{ matrix.release.sha256 }}
      ARCHIVE: openssl-${{ matrix.release.version }}-${{ matrix.platform }}.tar.gz
      MACOSX_DEPLOYMENT_TARGET: "11.0"
    steps:
      - *SafeCheckout
      - name: Probe preinstalled toolchain
        if: runner.os == 'Windows'
        continue-on-error: true
        shell: pwsh
        env: { MATRIX: "${{ toJSON(matrix) }}" }
        run: |
          $tool    = ($env:MATRIX | ConvertFrom-Json).tool
          $missing = @(
            foreach ($name in 'perl', 'cl', 'link', 'nmake', 'vswhere', 'Enter-VsDevShell', $tool) {
              $command = Get-Command $name -ErrorAction Ignore | Select-Object -First 1
              Write-Host ('{0,-18} {1}' -f $name, ($command.Source ?? 'missing'))
              if (-not $command) { $name }
            }
            foreach ($name in 'INCLUDE', 'LIB', 'VCToolsInstallDir', 'WindowsSdkDir') {
              $value = [Environment]::GetEnvironmentVariable($name)
              Write-Host ('{0,-18} {1}' -f $name, ($value ?? 'unset'))
              if (-not $value) { $name }
            }
          )
          if ($missing) { "::warning::Not present before setup: $($missing -join ', ')"; exit 1 }
      - name: Build
        shell: pwsh
        env:
          MATRIX: "${{ toJSON(matrix) }}"
          NASM: '{ "version": "2.16.01", "sha256": "029eed31faf0d2c5f95783294432cbea6c15bf633430f254bb3c1f195c67ca3a" }'
        run: |
          $ErrorActionPreference                   = 'Stop'
          $PSNativeCommandUseErrorActionPreference = $true

          $matrix  = $env:MATRIX | ConvertFrom-Json
          $tmp     = $env:RUNNER_TEMP
          $source  = "openssl-$env:VERSION"
          $options = 'no-shared', 'no-module', 'no-tests'

          function Save-Verified([string] $Uri, [string] $OutFile, [string] $Sha256) {
            Invoke-WebRequest $Uri -OutFile $OutFile -MaximumRetryCount 4 -RetryIntervalSec 2
            $actual = (Get-FileHash $OutFile -Algorithm SHA256).Hash
            if ($actual -ne $Sha256) { throw "$OutFile has SHA-256 $actual, expected $Sha256" }
          }

          if ($IsLinux) {
            & docker buildx build .github/openssl --build-arg "VERSION=$env:VERSION" --build-arg "SHA256=$env:SHA256" --output "type=local,dest=$tmp/export"
            $root = "$tmp/export/usr/local"
          }
          else {
            Save-Verified "https://github.com/openssl/openssl/releases/download/$source/$source.tar.gz" "$tmp/$source.tar.gz" $env:SHA256
            & tar -xzf "$tmp/$source.tar.gz" -C $tmp
            Set-Location "$tmp/$source"
          }

          if ($IsMacOS) {
            $root = "$tmp/root/usr/local"
            & ./Configure --prefix=/usr/local --openssldir=/usr/local/ssl --libdir=lib @options
            & make -j (sysctl -n hw.ncpu) build_sw
            & make DESTDIR="$tmp/root" install_sw install_ssldirs
            & otool -L "$root/bin/openssl"
          }

          if ($IsWindows) {
            $root   = 'C:/openssl'
            $known  = & perl Configure LIST
            $target = $matrix.'configure-targets' | Where-Object { $_ -in $known } | Select-Object -First 1
            if (-not $target) { throw "OpenSSL $env:VERSION has none of $($matrix.'configure-targets' -join ', ')" }

            if ($matrix.tool -eq 'nasm') {
              $nasm = $env:NASM | ConvertFrom-Json
              $zip  = "nasm-$($nasm.version)-win64.zip"
              Save-Verified "https://www.nasm.us/pub/nasm/releasebuilds/$($nasm.version)/win64/$zip" "$tmp/$zip" $nasm.sha256
              Expand-Archive "$tmp/$zip" -DestinationPath $tmp
              $env:PATH = "$tmp/nasm-$($nasm.version);$env:PATH"
            }

            $vs   = vswhere -latest -products * -property installationPath
            $arch = $matrix.'msvc-arch'
            Import-Module "$vs/Common7/Tools/Microsoft.VisualStudio.DevShell.dll"
            Enter-VsDevShell -VsInstallPath $vs -SkipAutomaticLocation -DevCmdArguments "-arch=$arch -host_arch=$arch"

            Get-Command perl, nmake, cl, $matrix.tool | Format-Table Name, Source
            if (Select-String Configure -Pattern static-vcruntime -Quiet) { $options += 'enable-static-vcruntime' }
            & perl Configure $target --prefix=$root --openssldir=$root/ssl @options
            & nmake build_sw
            & nmake install_sw install_ssldirs
            & dumpbin /dependents "$root/bin/openssl.exe"
          }

          $openssl = Join-Path $root bin ($IsWindows ? 'openssl.exe' : 'openssl')
          & $openssl version -a
          & tar -C $root -czf "$tmp/$env:ARCHIVE" .
      - uses: *Upload
        with:
          name: openssl-${{ matrix.release.version }}-${{ matrix.platform }}
          path: ${{ runner.temp }}/${{ env.ARCHIVE }}
          if-no-files-found: error
          retention-days: 1

  publish:
    name: Tarballs ${{ matrix.release.version || 'none' }}
    needs: [resolve, image, tarball]
    if: *IsMaster
    runs-on: *Ubuntu
    timeout-minutes: 10
    permissions: *WritePkgAttestIdToken
    strategy: { fail-fast: true, matrix: { release: "${{ fromJSON(needs.resolve.outputs.publishes) }}", exclude: [release: none] } }
    steps:
      - parallel:
          - if: &Release matrix.release
            uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
            with:
              pattern: openssl-${{ matrix.release.version }}-*
              merge-multiple: true
              path: &PublishArtefact ${{ runner.temp }}/dist
          - { if: *Release, uses: *Oras }
      - { if: *Release, uses: *Attest, with: { subject-path: "${{ runner.temp }}/dist/*.tar.gz" } }
      - name: Push to GHCR
        if: *Release
        working-directory: *PublishArtefact
        env: { GH_TOKEN: *GHToken, v: *MatrixRelease, date: "${{ needs.resolve.outputs.date }}" }
        run: |
          ls -l
          files=()
          platforms=()
          for file in *.tar.gz; do
            files+=("${file}:application/vnd.oci.image.layer.v1.tar+gzip")
            platform="${file#"openssl-${v}-"}"
            platforms+=("${platform%.tar.gz}")
          done
          printf -v listed '%s, ' "${platforms[@]}"
          oras login ghcr.io --username "${GITHUB_ACTOR}" --password-stdin <<< "${GH_TOKEN}"
          oras push "${PREBUILT}:${v}-${BUILD}" --no-tty \
            --artifact-type application/vnd.kjanat.openssl.prebuilt.v1 \
            --annotation "org.opencontainers.image.source=${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}" \
            --annotation "org.opencontainers.image.version=${v}" \
            --annotation "dev.kjanat.openssl.upstream.tag=openssl-${v}" \
            --annotation "org.opencontainers.image.title=openssl-prebuilt" \
            --annotation "org.opencontainers.image.description=OpenSSL ${v} tarballs for ${listed%, }. Usage: ${USAGE}" \
            --annotation "org.opencontainers.image.licenses=Apache-2.0" \
            "${files[@]}"
          oras tag "${PREBUILT}:${v}-${BUILD}" "${v}-${date}"
          oras tag "${PREBUILT}:${v}-${BUILD}" "${v}"

  tags:
    name: Floating tags
    needs: [resolve, image, tarball, publish]
    if: ${{ !cancelled() && github.ref == 'refs/heads/master' && needs.resolve.result == 'success' && needs.image.result != 'failure' && needs.tarball.result != 'failure' && needs.publish.result != 'failure' }}
    runs-on: *Ubuntu
    timeout-minutes: 5
    permissions: { contents: read, packages: write }
    steps:
      - name: Point latest, alpha and beta
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        # pretty-yaml-ignore
        env:
          TOKEN:  ${{ github.token }}
          LATEST: ${{ needs.resolve.outputs.latest }}
          ALPHA:  ${{ needs.resolve.outputs.alpha  }}
          BETA:   ${{ needs.resolve.outputs.beta   }}
        with:
          script: |
            const { IMAGE, PREBUILT, TOKEN, LATEST, ALPHA, BETA } = process.env;
            const floating = { latest: LATEST, alpha: ALPHA, beta: BETA };
            const basic    = Buffer.from(`${context.actor}:${TOKEN}`).toString('base64');
            const accept   = [
              'application/vnd.oci.image.manifest.v1+json',
              'application/vnd.oci.image.index.v1+json',
              'application/vnd.docker.distribution.manifest.v2+json',
              'application/vnd.docker.distribution.manifest.list.v2+json',
            ].join(', ');

            async function registry(response, what) {
              if (!response.ok) throw new Error(`${what}: HTTP ${response.status} ${await response.text()}`);
              return response;
            }

            for (const image of [IMAGE, PREBUILT]) {
              const repository = image.replace(/^ghcr\.io\//, '');
              const auth = await registry(
                await fetch(`https://ghcr.io/token?service=ghcr.io&scope=repository:${repository}:pull,push`, { headers: { Authorization: `Basic ${basic}` } }),
                `token for ${repository}`,
              );
              const { token } = await auth.json();
              const base = `https://ghcr.io/v2/${repository}/manifests`;

              for (const [tag, version] of Object.entries(floating)) {
                if (!version) continue;
                const manifest = await registry(
                  await fetch(`${base}/${version}`, { headers: { Authorization: `Bearer ${token}`, Accept: accept } }),
                  `${image}:${version}`,
                );
                const put = await registry(
                  await fetch(`${base}/${tag}`, {
                    method: 'PUT',
                    headers: { Authorization: `Bearer ${token}`, 'Content-Type': manifest.headers.get('content-type') },
                    body: Buffer.from(await manifest.arrayBuffer()),
                  }),
                  `${image}:${tag}`,
                );
                core.info(`${image}:${tag} -> ${version} (${put.headers.get('docker-content-digest')})`);
              }
            }

files..github/workflows/publish.yml:
name: Publish

on:
  push: { tags: ["v*.*.*"] }
  pull_request: { branches: [master] }

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' }}

permissions: { contents: read }

defaults: { run: { shell: "bash -euo pipefail {0}" } }

jobs:
  test:
    name: Test
    uses: $/.github/workflows/test.yml
    if: github.event_name == 'push'
    permissions: { contents: read, id-token: write, attestations: read }

  validate:
    name: Validate version
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions: { contents: read }
    if: github.repository == 'kjanat/micro509' && (github.event_name == 'push' || github.event.pull_request.head.repo.full_name == github.repository) # pretty-yaml-ignore
    outputs:
      version:    ${{ steps.version.outputs.version    }}
      jsr_url:    ${{ steps.version.outputs.jsr_url    }}
      npm_url:    ${{ steps.version.outputs.npm_url    }}
      is_tag:     ${{ steps.version.outputs.is_tag     }}
      prerelease: ${{ steps.version.outputs.prerelease }}
      is_stable:  ${{ steps.version.outputs.is_stable  }}
      mode:       ${{ steps.version.outputs.mode       }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with: { persist-credentials: false }
      - uses: $/.github/actions/release-validate
        id: version
        with: { event-name: "${{ github.event_name }}", ref-name: "${{ github.ref_name }}" }

  publish-jsr:
    name: JSR (${{ needs.validate.outputs.mode }})
    needs: [test, validate]
    if: ${{ !cancelled() && needs.validate.result == 'success' && (needs.test.result == 'success' || (needs.test.result == 'skipped' && github.event_name != 'push')) }}
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions: { contents: read, id-token: write } # pretty-yaml-ignore
    environment:
      name: ${{ case(needs.validate.outputs.is_tag == 'true', 'jsr', '') }}
      url:  ${{ case(needs.validate.outputs.is_tag == 'true', needs.validate.outputs.jsr_url, '') }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with: { persist-credentials: false }
      - uses: $/.github/actions/setup
        id: setup
        with: { install-bun: "true" }
      - name: Install dependencies and build (tsdown regenerates jsr.json)
        run: runner install -f build fmt
      - shell: pwsh
        env: { OUTPUTS: "${{ toJSON(needs.validate.outputs) }}" }
        run: |
          $outputs = $env:OUTPUTS | ConvertFrom-Json
          if ($outputs.is_tag -ne 'true') { bunx jsr publish --dry-run; exit $LASTEXITCODE }

          $pkg = Get-Content jsr.json | ConvertFrom-Json
          $meta = try { Invoke-RestMethod ("https://jsr.io/{0}/meta.json" -f $pkg.name) -ErrorAction Stop } catch {}
          if ($meta.versions.PSObject.Properties.Name -contains $pkg.version) { "::notice::{0}@{1} already on JSR, skipping" -f $pkg.name, $pkg.version; exit 0 }

          bunx jsr publish; exit $LASTEXITCODE

  publish-npm:
    name: npm (${{ needs.validate.outputs.mode }})
    needs: [test, validate]
    if: ${{ !cancelled() && needs.validate.result == 'success' && (needs.test.result == 'success' || (needs.test.result == 'skipped' && github.event_name != 'push')) }}
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions: { contents: read, id-token: write }
    environment:
      name: ${{ needs.validate.outputs.is_tag == 'true' && 'npm' || '' }}
      url: ${{ needs.validate.outputs.is_tag == 'true' && needs.validate.outputs.npm_url || '' }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with: { persist-credentials: false }
      - uses: $/.github/actions/setup
        id: setup
        with: { install-bun: true, install-node: true, update-npm: true, node-registry-url: https://registry.npmjs.org }
      - run: runner install -f build
      - shell: pwsh
        env: { OUTPUTS: "${{ toJSON(needs.validate.outputs) }}" }
        run: |
          $outputs = ConvertFrom-Json $env:OUTPUTS
          $pkg = Get-Content package.json | ConvertFrom-Json
          $versionsJson = bun info $pkg.name versions --json 2>$null
          $versions = if ($LASTEXITCODE -eq 0) { $versionsJson | ConvertFrom-Json } else { @() }

          if ($versions -contains $pkg.version) { "::notice::{0}@{1} already on npm, skipping" -f $pkg.name, $pkg.version; exit 0 }
          if ($outputs.is_tag -ne 'true') { npm publish --dry-run; exit $LASTEXITCODE }

          $publishArgs = @('--provenance', '--access', 'public')
          if ($outputs.prerelease -eq 'true') { $publishArgs += @('--tag', 'beta') }

          npm publish @publishArgs; exit $LASTEXITCODE

  release:
    name: GitHub Release
    needs: [validate, publish-jsr, publish-npm]
    if: needs.validate.outputs.is_tag == 'true'
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions: { contents: write }
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7
        with: { persist-credentials: false }
      - uses: $/.github/actions/setup
        with: { install-node: true, update-npm: true }
      - shell: pwsh
        env:
          GH_TOKEN: ${{ github.token }}
          GH_REPO: ${{ github.repository }}
          TAG: ${{ github.ref_name }}
          OUTPUTS: "${{ toJSON(needs.validate.outputs) }}"
        run: |
          $outputs = ConvertFrom-Json $env:OUTPUTS
          $pkg = Get-Content package.json | ConvertFrom-Json
          $spec = "{0}@{1}" -f $pkg.name, $pkg.version
          $asset = 'dist.tar.gz'

          $release = gh release view $env:TAG --json isDraft,isImmutable,assets 2>$null | ConvertFrom-Json
          $attached = $release.assets.name -contains $asset
          $needsAsset = $outputs.is_stable -eq 'true' -and -not $attached

          if ($needsAsset -and $release -and -not $release.isDraft -and $release.isImmutable) {
            "::error::{0} is published and immutable, and carries no {1}" -f $env:TAG, $asset
            exit 1
          }

          $files = @()
          if ($needsAsset) {
            $blob = $null
            foreach ($attempt in 1..10) {
              $blob = npm pack $spec --silent 2>$null
              if ($LASTEXITCODE -eq 0 -and $blob) { break }
              "::notice::{0} not on the registry yet (attempt {1}/10)" -f $spec, $attempt
              $blob = $null
              Start-Sleep -Seconds 15
            }
            if (-not $blob) { "::error::{0} never appeared on the registry" -f $spec; exit 1 }

            Move-Item -Force $blob $asset
            $files = @($asset)
          }

          $releaseArgs = @()
          if ($outputs.prerelease -eq 'true') { $releaseArgs += '--prerelease' }

          if ($release) {
            if ($files) { gh release upload $env:TAG @files --clobber; if ($LASTEXITCODE -ne 0) { exit 1 } }
            gh release edit $env:TAG --draft=false @releaseArgs
          } else {
            gh release create $env:TAG --generate-notes @releaseArgs @files
          }
          exit $LASTEXITCODE

  deploy-docs:
    name: Deploy docs
    needs: [validate, release]
    if: needs.validate.outputs.is_tag == 'true' && needs.validate.outputs.is_stable == 'true'
    permissions: { contents: write }
    uses: $/.github/workflows/deploy-site.yml
    with:
      version: ${{ github.ref_name }}
    secrets:
      CF_DEPLOY_HOOK_URL: ${{ secrets.CF_DEPLOY_HOOK_URL }}

