import { runSmoke } from '#smoke';

const resolvedDefaultRootExport = new URL(
	pkg['exports']['.']['default'],
	import.meta.resolve('#pkg'),
);
/** @type {typeof import('#micro509')} */
const micro509 = await import(resolvedDefaultRootExport.href);

const resolvedCryptoExport = new URL(
	pkg['exports']['./crypto']['default'],
	import.meta.resolve('#pkg'),
);
/** @type {typeof import('#micro509/crypto')} */
const cryptoApi = await import(resolvedCryptoExport.href);

const resolvedKdfExport = new URL(pkg['exports']['./kdf']['default'], import.meta.resolve('#pkg'));
/** @type {typeof import('#micro509/kdf')} */
const kdfApi = await import(resolvedKdfExport.href);

const resolvedSshExport = new URL(pkg.exports['./ssh'].default, import.meta.resolve('#pkg'));
/** @type {typeof import('#micro509/ssh')} */
