import { describe, expect, it } from 'bun:test';
import { readdir, readFile } from 'node:fs/promises';
import { URL } from 'node:url';
import type { ParsedCertificate, ParsedCertificateRevocationList } from '#micro509';
import {
	checkChainRevocation,
	parseCertificateDer,
	parseCertificateRevocationListDerOrThrow,
	unwrap,
	verifyCertificateChain,
} from '#micro509';
import type { PkitsCase } from '#test/pkits/manifest';
import { PKITS_CASES } from '#test/pkits/manifest';

const PKITS_VALIDATION_TIME = new Date('2011-04-15T00:00:00Z');
const REVOCATION_SECTIONS = new Set(['4.4', '4.5', '4.14', '4.15']);
const REVOCATION_TEST_NUMBERS = new Set(['4.7.4', '4.7.5']);
// PKITS cases that exercise DSA. micro509 is WebCrypto-native and does not
// support DSA by design, so these "valid DSA" chains fail with
// `unsupported_signature_algorithm_parameters`. Tracked with `it.failing` so the
// suite flags us if DSA support ever lands (the test would start passing).
const UNSUPPORTED_ALGORITHM_TESTS = new Set(['4.1.4', '4.1.5']);
// PKITS 4.8.19's explicitText is 310 characters; the application may reject it.
const OVERSIZED_EXPLICIT_TEXT_TEST = '4.8.19';
const USER_NOTICE_QUALIFIER_TITLE = 'User Notice Qualifier';

const certificateDerCache = new Map<string, Promise<Uint8Array>>();
const parsedCertificateCache = new Map<string, Promise<ParsedCertificate>>();
const parsedCrlCache = new Map<string, Promise<ParsedCertificateRevocationList>>();

function shouldEvaluateRevocation(pkitsCase: PkitsCase): boolean {
	return (
		REVOCATION_SECTIONS.has(pkitsCase.section) || REVOCATION_TEST_NUMBERS.has(pkitsCase.testNumber)
	);
}

async function readPkitsFixture(path: string): Promise<Uint8Array> {
	return new Uint8Array(await readFile(new URL(path, import.meta.url)));
}

async function readPkitsCertificateDer(name: string): Promise<Uint8Array> {
	const cached = certificateDerCache.get(name);
	if (cached !== undefined) {
		return cached;
	}
	const pending = readPkitsFixture(`./fixtures/pkits/certs/${name}.crt`);
	certificateDerCache.set(name, pending);
	return await pending;
}

async function readPkitsParsedCertificate(name: string): Promise<ParsedCertificate> {
	const cached = parsedCertificateCache.get(name);
	if (cached !== undefined) {
		return cached;
	}
	const pending = readPkitsCertificateDer(name).then((der) => unwrap(parseCertificateDer(der)));
	parsedCertificateCache.set(name, pending);
	return await pending;
}

async function readPkitsParsedCrl(name: string): Promise<ParsedCertificateRevocationList> {
	const cached = parsedCrlCache.get(name);
	if (cached !== undefined) {
		return cached;
	}
	const pending = readPkitsFixture(`./fixtures/pkits/crls/${name}.crl`).then((der) =>
		parseCertificateRevocationListDerOrThrow(der),
	);
	parsedCrlCache.set(name, pending);
	return await pending;
}

let allPkitsCertificatesCache: ParsedCertificate[] | null = null;

async function loadAllPkitsCertificates(): Promise<ParsedCertificate[]> {
	if (allPkitsCertificatesCache !== null) {
		return allPkitsCertificatesCache;
	}

	const certDir = new URL('./fixtures/pkits/certs/', import.meta.url);
	const files = await readdir(certDir);
	const results = await Promise.allSettled(
		files
			.filter((f) => f.endsWith('.crt'))
			.map((f) => {
				const name = f.replace('.crt', '');
				return readPkitsParsedCertificate(name);
			}),
	);
	const certs = results
		.filter((r): r is PromiseFulfilledResult<ParsedCertificate> => r.status === 'fulfilled')
		.map((r) => r.value);

	allPkitsCertificatesCache = certs;
	return certs;
}

async function evaluatePkitsRevocation(
	chain: readonly ParsedCertificate[],
	crlNames: readonly string[],
): Promise<boolean> {
	const crlResults = await Promise.allSettled(crlNames.map(readPkitsParsedCrl));
	const crls = crlResults
		.filter(
			(r): r is PromiseFulfilledResult<ParsedCertificateRevocationList> => r.status === 'fulfilled',
		)
		.map((r) => r.value);

	const result = await checkChainRevocation({
		chain,
		crls,
		extraCertificates: await loadAllPkitsCertificates(),
		policy: { mode: 'hard-fail' },
		at: PKITS_VALIDATION_TIME,
	});

	return result.value.decision === 'allow';
}

describe('PKITS harness', () => {
	const pkitsCases: readonly PkitsCase[] = PKITS_CASES;
	const casesBySection = new Map<string, PkitsCase[]>();
	for (const pkitsCase of pkitsCases) {
		const sectionCases = casesBySection.get(pkitsCase.section);
		if (sectionCases === undefined) {
			casesBySection.set(pkitsCase.section, [pkitsCase]);
			continue;
		}
		sectionCases.push(pkitsCase);
	}

	for (const [section, sectionCases] of casesBySection) {
		describe(section, () => {
			for (const pkitsCase of sectionCases) {
				// Revocation cases search the full corpus. Run serially so concurrent
				// coverage work does not consume each case's timeout on CI runners.
				const register = UNSUPPORTED_ALGORITHM_TESTS.has(pkitsCase.testNumber)
					? it.serial.failing
					: it.serial;
				register(`${pkitsCase.testNumber} ${pkitsCase.title}`, () => runPkitsCase(pkitsCase));
			}
		});
	}
});

// PKITS 4.8.19: "Since the explicitText exceeds the maximum size of 200
// characters, the application may choose to reject the certificate."
describe('PKITS 4.8.19 oversized explicitText', () => {
	const oversizedCase = PKITS_CASES.find(
		(pkitsCase) => pkitsCase.testNumber === OVERSIZED_EXPLICIT_TEXT_TEST,
	);
	if (oversizedCase === undefined) {
		throw new Error(`PKITS manifest lacks ${OVERSIZED_EXPLICIT_TEXT_TEST}`);
	}
	const otherUserNoticeCases = PKITS_CASES.filter(
		(pkitsCase) =>
			pkitsCase.title.startsWith(USER_NOTICE_QUALIFIER_TITLE) &&
			pkitsCase.testNumber !== OVERSIZED_EXPLICIT_TEXT_TEST,
	);

	async function userNotices(pkitsCase: PkitsCase) {
		const leaf = await readPkitsParsedCertificate(pkitsLeafName(pkitsCase));
		return (leaf.certificatePolicies ?? []).flatMap((policy) =>
			(policy.policyQualifiers ?? []).flatMap((qualifier) =>
				qualifier.type === 'userNotice' ? [qualifier] : [],
			),
		);
	}

	it('keeps the 310-character explicitText whole and reports its size', async () => {
		const notices = await userNotices(oversizedCase);
		expect(notices).toHaveLength(1);
		expect([...(notices[0]?.explicitText ?? '')]).toHaveLength(310);
		expect(notices[0]?.oversizedExplicitText).toEqual({ characters: 310, limit: 200 });
	});

	it('rejects the path under rejectOversizedDisplayText for that reason alone', async () => {
		expect(await verifyPkitsPath(oversizedCase)).toMatchObject({ ok: true });
		expect(
			await verifyPkitsPath(oversizedCase, { rejectOversizedDisplayText: true }),
		).toMatchObject({
			ok: false,
			code: 'display_text_oversized',
			message:
				'certificate policy 2.16.840.1.101.3.2.1.48.1 carries a user notice explicitText of 310 characters',
			index: 0,
			details: {
				subjectCommonName: 'User Notice Qualifier EE Certificate Test19',
				expected: '200',
				actual: '310',
				userNoticeField: 'explicitText',
			},
		});
	});

	it.each(otherUserNoticeCases.map((pkitsCase) => [pkitsCase.testNumber, pkitsCase] as const))(
		'%s validates under rejectOversizedDisplayText as the manifest expects (run %#)',
		async (_testNumber, pkitsCase) => {
			const notices = await userNotices(pkitsCase);
			expect(notices.length).toBeGreaterThan(0);
			expect(
				notices.every(
					(notice) =>
						notice.oversizedExplicitText === undefined &&
						notice.noticeRef?.oversizedOrganization === undefined,
				),
			).toBe(true);
			const result = await verifyPkitsPath(pkitsCase, { rejectOversizedDisplayText: true });
			expect(result.ok).toBe(pkitsCase.shouldValidate);
		},
	);
});

function pkitsLeafName(pkitsCase: PkitsCase): string {
	const leafName = pkitsCase.certs[pkitsCase.certs.length - 1];
	if (leafName === undefined) {
		throw new Error(`PKITS case ${pkitsCase.testNumber} is missing its leaf`);
	}
	return leafName;
}

async function verifyPkitsPath(
	pkitsCase: PkitsCase,
	options: { readonly rejectOversizedDisplayText?: boolean } = {},
): Promise<Awaited<ReturnType<typeof verifyCertificateChain>>> {
	const rootName = pkitsCase.certs[0];
	if (rootName === undefined) {
		throw new Error(`PKITS case ${pkitsCase.testNumber} is missing its root`);
	}
	const [leaf, root, intermediates] = await Promise.all([
		readPkitsCertificateDer(pkitsLeafName(pkitsCase)),
		readPkitsCertificateDer(rootName),
		Promise.all(pkitsCase.certs.slice(1, -1).map(readPkitsCertificateDer)),
	]);
	return await verifyCertificateChain({
		leaf,
		intermediates,
		roots: [root],
		at: PKITS_VALIDATION_TIME,
		...(pkitsCase.initialPolicySet === undefined
			? {}
			: { initialPolicySet: pkitsCase.initialPolicySet }),
		...(pkitsCase.requireExplicitPolicy === undefined
			? {}
			: { requireExplicitPolicy: pkitsCase.requireExplicitPolicy }),
		...(pkitsCase.inhibitPolicyMapping === undefined
			? {}
			: { inhibitPolicyMapping: pkitsCase.inhibitPolicyMapping }),
		...(pkitsCase.inhibitAnyPolicy === undefined
			? {}
			: { inhibitAnyPolicy: pkitsCase.inhibitAnyPolicy }),
		...options,
	});
}

async function runPkitsCase(pkitsCase: PkitsCase): Promise<void> {
	const verifyResult = await verifyPkitsPath(pkitsCase);
	if (!shouldEvaluateRevocation(pkitsCase) || !verifyResult.ok) {
		expect(verifyResult.ok).toBe(pkitsCase.shouldValidate);
		return;
	}
	const revocationResult =
		pkitsCase.crls.length > 0
			? await evaluatePkitsRevocation(verifyResult.value.chain, pkitsCase.crls)
			: true;
	expect(revocationResult).toBe(pkitsCase.shouldValidate);
}
